mapper.select:
SELECT l.item_id,l.topic_id FROM knowledge_item_topic l
JOIN knowledge_item i ON i.id=l.item_id AND i.owner_id=#{owner}
JOIN knowledge_topic t ON t.id=l.topic_id AND t.owner_id=i.owner_id WHERE i.id IN
#{id}
ORDER BY l.item_id,l.topic_id

SELECT e.id,e.item_id FROM knowledge_outbox e WHERE e.owner_id=#{owner} AND e.id > #{boundary}
  AND NOT EXISTS(SELECT 1 FROM search_generation_event a WHERE a.owner_id=e.owner_id AND a.generation=#{generation} AND a.event_id=e.id)
ORDER BY e.id LIMIT #{limit}
